std::wstring wide(const std::string& s){if(s.empty())return {};const int n=MultiByteToWideChar(CP_UTF8,MB_ERR_INVALID_CHARS,s.data(),static_cast<int>(s.size()),nullptr,0);if(n<=0)return L"";std::wstring out(n,L'\0');MultiByteToWideChar(CP_UTF8,0,s.data(),static_cast<int>(s.size()),out.data(),n);return out;}
std::string utf8Text(const std::wstring& s){if(s.empty())return {};const int n=WideCharToMultiByte(CP_UTF8,0,s.data(),static_cast<int>(s.size()),nullptr,0,nullptr,nullptr);std::string out(n,'\0');WideCharToMultiByte(CP_UTF8,0,s.data(),static_cast<int>(s.size()),out.data(),n,nullptr,nullptr);return out;}
void fill(HDC dc,const RECT& r,COLORREF color){auto brush=CreateSolidBrush(color);FillRect(dc,&r,brush);DeleteObject(brush);}
void roundBox(HDC dc,RECT r,COLORREF color,int radius=16){auto brush=CreateSolidBrush(color);auto old=SelectObject(dc,brush);auto pen=CreatePen(PS_SOLID,1,color);auto oldPen=SelectObject(dc,pen);RoundRect(dc,r.left,r.top,r.right,r.bottom,radius,radius);SelectObject(dc,oldPen);SelectObject(dc,old);DeleteObject(pen);DeleteObject(brush);}
HICON appIcon(){auto screen=GetDC(nullptr);auto dc=CreateCompatibleDC(screen);auto bitmap=CreateCompatibleBitmap(screen,32,32);auto old=SelectObject(dc,bitmap);RECT r{0,0,32,32};fill(dc,r,RGB(219,232,211));auto brush=CreateSolidBrush(sage);auto prior=SelectObject(dc,brush);for(POINT p: {POINT{16,10},POINT{10,21},POINT{22,21}})Ellipse(dc,p.x-2,p.y-2,p.x+2,p.y+2);SelectObject(dc,prior);DeleteObject(brush);SelectObject(dc,old);const BYTE maskBits[128]{};auto mask=CreateBitmap(32,32,1,1,maskBits);ICONINFO info{TRUE,0,0,mask,bitmap};auto result=CreateIconIndirect(&info);DeleteObject(mask);DeleteObject(bitmap);DeleteDC(dc);ReleaseDC(nullptr,screen);return result;}
