        std::size_t prefix=0;while(prefix<next.size()&&prefix<previous.size()&&next[prefix]==previous[prefix])++prefix;if(prefix&&prefix<next.size()&&next[prefix]>=0xdc00&&next[prefix]<=0xdfff)--prefix;SendMessageW(control,WM_SETREDRAW,FALSE,0);SendMessageW(control,EM_SETREADONLY,FALSE,0);CHARRANGE changed{static_cast<LONG>(prefix),-1};SendMessageW(control,EM_EXSETSEL,0,reinterpret_cast<LPARAM>(&changed));SendMessageW(control,EM_REPLACESEL,FALSE,reinterpret_cast<LPARAM>(next.c_str()+prefix));SendMessageW(control,EM_SETREADONLY,TRUE,0);
