void DesktopHost::update(){auto& a=*impl_;for(const auto& request:a.app.takeDesktopRequests()){if(request.value("mode",std::string{})=="window")a.show();else a.showFloating(request.at("x"),request.at("y"));}a.animate();a.pollAudio();if(GetTickCount64()<a.nextPoll)return;a.nextPoll=GetTickCount64()+250;const auto response=a.app.request({"GET","/api/chat",""});if(response.status!=200)return;const auto state=Json::parse(response.body);Json transcript=Json::array();bool waitingSpeech=false;for(const auto& message:state.at("messages")){transcript.push_back({{"id",message.at("id")},{"text",message.at("text")}});const auto playback=message.value("playback",Json::object()).value("state",std::string{});if(playback=="waiting")waitingSpeech=true;}const auto signature=transcript.dump();const bool changed=signature!=a.signature;const bool presentationChanged=state.at("messages")!=a.messages;const bool busy=state.at("busy"),paused=state.at("paused"),mock=state.at("mock"),failed=state.at("call_failed");const auto failureMessage=state.contains("call_error")&&state.at("call_error").is_object()?state.at("call_error").value("message",std::string{}):std::string{};auto speechMessage=state.value("speech_error",std::string{});if(speechMessage.empty()&&waitingSpeech)speechMessage="正在准备声音……";const bool statusChanged=speechMessage!=a.speechMessage||failureMessage!=a.failureMessage||busy!=a.busy||paused!=a.paused||mock!=a.mock||failed!=a.failed;a.speechMessage=speechMessage;a.failureMessage=failureMessage;a.busy=busy;a.paused=paused;a.mock=mock;a.failed=failed;if(changed||presentationChanged){a.replaceMessages(state.at("messages"));a.signature=signature;}const bool enabled=!busy&&!paused;if((IsWindowEnabled(a.send)!=FALSE)!=enabled)EnableWindow(a.send,enabled);if(changed||presentationChanged||statusChanged){a.syncTranscripts();InvalidateRect(a.window,nullptr,FALSE);if(a.floatWindow)InvalidateRect(a.floatWindow,nullptr,FALSE);}}
